//! Scanning, edit files, queries, snapshots, and fingerprints, on temporary
//! folders of stand-in photos (generated bytes with real signatures).

use std::fs;
use std::path::{Path, PathBuf};

use seura_library::{EditFileState, Filter, Index, SNAPSHOT_FILE, Scope, fingerprint_file, to_hex};
use tempfile::TempDir;

const JPEG: &[u8] = &[0xFF, 0xD8, 0xFF, 0xE1];
const PNG: &[u8] = b"\x89PNG\r\n\x1a\n";
const HEIC: &[u8] = b"\0\0\0\x18ftypheic\0\0\0\0";

struct Folder {
    dir: TempDir,
}

impl Folder {
    fn new() -> Folder {
        Folder {
            dir: tempfile::tempdir().unwrap(),
        }
    }

    fn root(&self) -> PathBuf {
        seura_library_root(self.dir.path())
    }

    fn write(&self, name: &str, bytes: &[u8]) -> PathBuf {
        let path = self.root().join(name);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, bytes).unwrap();
        path
    }

    fn photo(&self, name: &str, signature: &[u8]) -> PathBuf {
        let mut bytes = signature.to_vec();
        bytes.extend(name.bytes().cycle().take(500));
        self.write(name, &bytes)
    }

    fn edit_file(&self, photo: &str, tags: &[&str], rating: u8, edited: bool) {
        let mut json = serde_json::json!({
            "format": "seura-edit",
            "formatVersion": "1.0",
            "photo": {
                "file": Path::new(photo).file_name().unwrap().to_str().unwrap(),
                "size": 1, "sha256": "0".repeat(64), "width": 1, "height": 1
            },
            "tags": tags,
        });
        if rating > 0 {
            json["rating"] = rating.into();
        }
        if edited {
            json["operations"] = serde_json::json!([{ "id": "seura.exposure", "version": 1, "params": { "ev": 0.5 } }]);
        }
        if tags.is_empty() {
            json.as_object_mut().unwrap().remove("tags");
        }
        self.write(
            &format!("{photo}.seura.json"),
            &serde_json::to_vec(&json).unwrap(),
        );
    }
}

/// The library root as the index stores it (the real path, so on macOS
/// `/var` becomes `/private/var`).
fn seura_library_root(path: &Path) -> PathBuf {
    let mut index = Index::new();
    index.add_root(path).unwrap();
    index.roots()[0].clone()
}

fn names(index: &Index, ids: &[seura_library::PhotoId]) -> Vec<String> {
    let mut names: Vec<String> = ids
        .iter()
        .map(|id| index.photo(*id).unwrap().name.to_string())
        .collect();
    names.sort();
    names
}

fn photo(index: &Index, name: &str) -> seura_library::Photo {
    let id = index
        .query(Scope::All, &Filter::default())
        .into_iter()
        .find(|id| &*index.photo(*id).unwrap().name == name)
        .unwrap();
    index.photo(id).unwrap().clone()
}

fn all(index: &Index) -> Vec<String> {
    names(index, &index.query(Scope::All, &Filter::default()))
}

#[test]
fn scanning_finds_photos_and_skips_everything_else() {
    let folder = Folder::new();
    folder.photo("IMG_0001.JPG", JPEG);
    folder.photo("Summer/beach.png", PNG);
    folder.photo("Summer/Day 2/IMG_0002.heic", HEIC);
    // Ignored (LIB-7, LIB-8): hidden and system items, other formats, a
    // Live Photo's video, edit files, and a file whose bytes aren't a photo.
    folder.photo(".hidden/IMG_0003.jpg", JPEG);
    folder.photo(".IMG_0004.jpg", JPEG);
    folder.photo("$RECYCLE.BIN/IMG_0005.jpg", JPEG);
    folder.photo(".Trashes/IMG_0006.jpg", JPEG);
    folder.write("IMG_0002.MOV", b"\0\0\0\x14ftypqt  ");
    folder.write("notes.txt", b"hello");
    folder.write("renamed.jpg", b"this is not a photo");
    folder.write("Empty/readme.txt", b"no photos here");

    let mut index = Index::new();
    let report = index.scan(&folder.root());
    assert_eq!(all(&index), ["IMG_0001.JPG", "IMG_0002.heic", "beach.png"]);
    assert_eq!((report.photos, report.added), (3, 3));
    assert!(index.folder_id(&folder.root().join("Empty")).is_none());
    assert!(
        index
            .folder_id(&folder.root().join("Summer").join("Day 2"))
            .is_some()
    );
}

#[test]
fn rescanning_reads_only_what_changed() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    folder.photo("b.jpg", JPEG);
    folder.photo("Old/c.jpg", JPEG);
    let mut index = Index::new();
    index.scan(&folder.root());

    let report = index.scan(&folder.root());
    assert_eq!((report.added, report.changed, report.removed), (0, 0, 0));

    folder.write("a.jpg", &[JPEG, b"different and longer contents"].concat());
    fs::remove_file(folder.root().join("b.jpg")).unwrap();
    fs::remove_dir_all(folder.root().join("Old")).unwrap();
    folder.photo("d.png", PNG);
    let report = index.scan(&folder.root());
    assert_eq!((report.added, report.changed, report.removed), (1, 1, 2));
    assert_eq!(all(&index), ["a.jpg", "d.png"]);
    assert!(index.folder_id(&folder.root().join("Old")).is_none());
}

#[test]
fn a_photo_replaced_by_something_else_is_dropped() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    let mut index = Index::new();
    index.scan(&folder.root());
    folder.write("a.jpg", b"now a text file with a photo's name");
    let report = index.scan(&folder.root());
    assert_eq!(report.removed, 1);
    assert!(index.is_empty());
}

#[test]
fn edit_files_supply_tags_rating_and_the_edited_flag() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    folder.photo("b.jpg", JPEG);
    folder.photo("c.jpg", JPEG);
    folder.edit_file("a.jpg", &["family", "vacation/2026"], 4, true);
    folder.edit_file("b.jpg", &["family"], 0, false);
    folder.write("c.jpg.seura.json", b"{ not valid");

    let mut index = Index::new();
    let report = index.scan(&folder.root());
    assert_eq!(
        report.unreadable_edit_files,
        [folder.root().join("c.jpg.seura.json")]
    );

    assert_eq!(
        photo(&index, "a.jpg").edit_file,
        EditFileState::Read { edited: true }
    );
    assert_eq!(photo(&index, "a.jpg").rating, 4);
    assert_eq!(
        photo(&index, "b.jpg").edit_file,
        EditFileState::Read { edited: false }
    );
    assert_eq!(photo(&index, "c.jpg").edit_file, EditFileState::Unreadable);
    assert_eq!(
        fs::read(folder.root().join("c.jpg.seura.json")).unwrap(),
        b"{ not valid"
    );

    // A changed edit file is re-read on the next scan.
    folder.edit_file("b.jpg", &["garden", "family"], 5, false);
    index.scan(&folder.root());
    assert_eq!(photo(&index, "b.jpg").rating, 5);
    let family = index.tag_id("family").unwrap();
    assert_eq!(
        names(&index, &index.query(Scope::Tag(family), &Filter::default())),
        ["a.jpg", "b.jpg"]
    );
}

#[test]
fn a_missing_library_folder_keeps_its_photos() {
    let folder = Folder::new();
    folder.photo("Drive/a.jpg", JPEG);
    let drive = folder.root().join("Drive");
    let mut index = Index::new();
    index.scan(&drive);

    let moved = folder.root().join("Unplugged");
    fs::rename(&drive, &moved).unwrap();
    let report = index.scan(&drive);
    assert!(report.unavailable);
    assert_eq!((report.photos, report.removed), (1, 0));
    assert_eq!(index.len(), 1);
}

#[test]
fn filters_and_search() {
    let folder = Folder::new();
    for (name, tags, rating, edited) in [
        ("IMG_1001.jpg", vec!["family/kids"], 5, true),
        ("IMG_1002.jpg", vec!["family/kids", "beach"], 3, false),
        ("Holiday/sunset.jpg", vec!["beach"], 4, true),
        ("Holiday/IMG_2001.png", vec![], 0, false),
    ] {
        folder.photo(name, if name.ends_with("png") { PNG } else { JPEG });
        if !tags.is_empty() || rating > 0 || edited {
            folder.edit_file(name, &tags, rating, edited);
        }
    }
    let mut index = Index::new();
    index.scan(&folder.root());
    let kids = index.tag_id("family/kids").unwrap();
    let beach = index.tag_id("beach").unwrap();
    let holiday = index.folder_id(&folder.root().join("Holiday")).unwrap();

    let query = |scope, filter: Filter| names(&index, &index.query(scope, &filter));
    // The folder's own photos only (BRW-1).
    assert_eq!(
        query(Scope::Folder(holiday), Filter::default()),
        ["IMG_2001.png", "sunset.jpg"]
    );
    let min_4 = Filter {
        min_rating: 4,
        ..Filter::default()
    };
    assert_eq!(query(Scope::All, min_4), ["IMG_1001.jpg", "sunset.jpg"]);
    let both = Filter {
        tags: vec![kids, beach],
        ..Filter::default()
    };
    assert_eq!(query(Scope::All, both), ["IMG_1002.jpg"]);
    let unedited = Filter {
        edited: Some(false),
        ..Filter::default()
    };
    assert_eq!(query(Scope::Tag(beach), unedited), ["IMG_1002.jpg"]);
    // Without a date taken, a photo is placed by its file date, as it sorts
    // (BRW-2, LIB-9): these were all written just now.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    let recent = Filter {
        taken: Some((now - 3_600, now + 3_600)),
        ..Filter::default()
    };
    assert_eq!(query(Scope::All, recent).len(), 4);
    let long_ago = Filter {
        taken: Some((0, now - 3_600)),
        ..Filter::default()
    };
    assert!(query(Scope::All, long_ago).is_empty());

    // Search matches file names and tags, ignoring case (FND-2).
    let search = |text| names(&index, &index.search(text, &Filter::default()));
    assert_eq!(search("img_1"), ["IMG_1001.jpg", "IMG_1002.jpg"]);
    assert_eq!(search("KIDS"), ["IMG_1001.jpg", "IMG_1002.jpg"]);
    assert_eq!(search("sun"), ["sunset.jpg"]);
    assert_eq!(search("BEACH"), ["IMG_1002.jpg", "sunset.jpg"]);
    assert_eq!(search(" ").len(), 4);
}

#[test]
fn the_snapshot_restores_the_index() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    folder.photo("Summer/b.png", PNG);
    folder.edit_file("a.jpg", &["family"], 4, true);
    let mut index = Index::new();
    index.add_root(&folder.root()).unwrap();
    index.scan(&folder.root());

    let cache = tempfile::tempdir().unwrap();
    index.save_snapshot(cache.path()).unwrap();
    let mut entries: Vec<String> = fs::read_dir(cache.path())
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect();
    entries.sort();
    assert_eq!(entries, ["README.txt", SNAPSHOT_FILE]);

    let loaded = Index::load_snapshot(cache.path()).expect("the snapshot loads");
    assert_eq!(loaded.roots(), index.roots());
    assert_eq!(all(&loaded), all(&index));
    let family = loaded.tag_id("family").unwrap();
    assert_eq!(
        names(
            &loaded,
            &loaded.query(Scope::Tag(family), &Filter::default())
        ),
        ["a.jpg"]
    );
    // Nothing changed on disk, so a scan after loading reads nothing.
    let mut loaded = loaded;
    let report = loaded.scan(&folder.root());
    assert_eq!((report.added, report.changed, report.removed), (0, 0, 0));
}

#[test]
fn a_date_taken_learned_from_decoding_is_new_once_and_kept_in_the_snapshot() {
    // #99: the app saves the index when decoding learns something new.
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    let mut index = Index::new();
    index.add_root(&folder.root()).unwrap();
    index.scan(&folder.root());
    let id = index.query(Scope::All, &Filter::default())[0];
    let made = seura_library::Made {
        width: 4000,
        height: 3000,
        taken: Some(1_783_881_720),
    };
    assert!(index.record_details(id, &made));
    assert!(!index.record_details(id, &made));
    // A thumbnail found later without a date doesn't forget the one known.
    let undated = seura_library::Made {
        taken: None,
        ..made
    };
    assert!(!index.record_details(id, &undated));

    let cache = tempfile::tempdir().unwrap();
    index.save_snapshot(cache.path()).unwrap();
    let loaded = Index::load_snapshot(cache.path()).expect("the snapshot loads");
    assert_eq!(photo(&loaded, "a.jpg").taken, Some(1_783_881_720));
}

#[test]
fn a_damaged_or_foreign_snapshot_is_ignored() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    let mut index = Index::new();
    index.scan(&folder.root());
    let bytes = index.to_snapshot();

    assert!(Index::from_snapshot(&bytes).is_some());
    assert!(Index::from_snapshot(&bytes[..bytes.len() / 2]).is_none());
    assert!(Index::from_snapshot(b"").is_none());
    assert!(Index::from_snapshot(b"something else entirely").is_none());
    let mut other_version = bytes.clone();
    other_version[8] = 99;
    assert!(Index::from_snapshot(&other_version).is_none());

    let cache = tempfile::tempdir().unwrap();
    assert!(
        Index::load_snapshot(cache.path()).is_none(),
        "no snapshot yet"
    );
}

#[test]
fn fingerprints_are_cached_until_the_file_changes() {
    let folder = Folder::new();
    let path = folder.photo("a.jpg", JPEG);
    let mut index = Index::new();
    index.scan(&folder.root());
    let id = index.query(Scope::All, &Filter::default())[0];

    let first = index.fingerprint(id).unwrap();
    assert_eq!(first, fingerprint_file(&path).unwrap());
    assert_eq!(to_hex(&first).len(), 64);
    assert_eq!(index.photo(id).unwrap().fingerprint, Some(first));

    folder.write(
        "a.jpg",
        &[JPEG, b"edited by another program, longer now"].concat(),
    );
    let second = index.fingerprint(id).unwrap();
    assert_ne!(first, second);
    assert_eq!(second, fingerprint_file(&path).unwrap());
}

/// Edits Seura can't show (FIL-5), and an original changed since its edits
/// were made (FIL-7).
#[test]
fn file_notices_count_what_isnt_shown_and_spot_a_changed_original() {
    let folder = Folder::new();
    let path = folder.photo("a.jpg", JPEG);
    let fingerprint = to_hex(&fingerprint_file(&path).unwrap());
    let edit_file = |operations: serde_json::Value| {
        let json = serde_json::json!({
            "format": "seura-edit",
            "formatVersion": "1.0",
            "photo": { "file": "a.jpg", "size": 504, "sha256": fingerprint },
            "operations": operations,
        });
        folder.write("a.jpg.seura.json", &serde_json::to_vec(&json).unwrap());
    };
    edit_file(serde_json::json!([
        { "id": "seura.exposure", "version": 1, "params": { "ev": 0.5 } },
        { "id": "com.example.toneCurve", "version": 4, "group": "tone",
          "params": { "points": [[0, 0], [1, 1]] } },
        { "id": "com.example.filmGrain", "version": 2, "group": "effects", "enabled": false,
          "params": { "amount": 12 } }
    ]));
    let mut index = Index::new();
    index.scan(&folder.root());
    let id = index.query(Scope::All, &Filter::default())[0];
    let index = std::sync::RwLock::new(index);

    // One enabled operation Seura doesn't render; the disabled one isn't
    // shown by anyone. The original is as the edits were made on.
    let notices = Index::file_notices(&index, id);
    assert_eq!(notices.not_shown, 1);
    assert!(!notices.original_changed);
    assert!(
        index
            .read()
            .unwrap()
            .photo(id)
            .unwrap()
            .fingerprint
            .is_some()
    );

    // Another program changes the photo.
    folder.write(
        "a.jpg",
        &[JPEG, b"edited by another program, longer now"].concat(),
    );
    index.write().unwrap().scan(&folder.root());
    assert!(Index::file_notices(&index, id).original_changed);

    // With only tags or a rating, there's nothing to line up.
    edit_file(serde_json::json!([]));
    index.write().unwrap().scan(&folder.root());
    assert_eq!(Index::file_notices(&index, id), Default::default());
}

/// A long scan doesn't hold the index (M2 slice 6): it can be read between
/// folders, and a library folder removed meanwhile stays removed.
#[test]
fn a_shared_scan_lets_the_index_be_read_and_stops_when_its_folder_goes() {
    const FOLDERS: usize = 500;
    let folder = Folder::new();
    for n in 0..FOLDERS {
        folder.photo(&format!("F{n:03}/a.jpg"), JPEG);
    }
    let root = folder.root();
    let mut index = Index::new();
    index.add_root(&root).unwrap();
    let index = std::sync::RwLock::new(index);

    let mut partly_scanned = false;
    std::thread::scope(|scope| {
        let scan = scope.spawn(|| Index::scan_shared(&index, &root, &root));
        while !scan.is_finished() {
            let len = index.read().unwrap().len();
            if len > 0 && len < FOLDERS {
                partly_scanned = true;
                index.write().unwrap().remove_root(&root);
                break;
            }
        }
    });

    assert!(partly_scanned, "the index was never read during the scan");
    let index = index.into_inner().unwrap();
    assert_eq!(index.len(), 0);
    assert!(index.folder_tree().is_empty());
}

#[test]
fn a_shared_scan_of_a_folder_no_longer_in_the_library_does_nothing() {
    let folder = Folder::new();
    folder.photo("a.jpg", JPEG);
    let index = std::sync::RwLock::new(Index::new());

    Index::scan_shared(&index, &folder.root(), &folder.root());

    assert_eq!(index.into_inner().unwrap().len(), 0);
}
